<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Update;

use RuntimeException;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariable;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TemplateVariableUpdateCheck
{
    public function __construct(public readonly TemplateVariableUpdateParams $input, public readonly TemplateVariable $current)
    {
    }
    public function reject(RuntimeException|ConstraintFail $fail): void
    {
        if ($fail instanceof ConstraintFail) {
            throw ConstraintException::ofFail($fail);
        } else {
            throw $fail;
        }
    }
}
